/* Genuine original item, native class/ATT/casting and 12i resource producers. */
import{loadArcaneGrimoireNative}from'./load-arcane-grimoire-native.mjs';import{slotRecoveryAuthorityProblems}from'../../src/data/lib/slot-recovery.js';import{arcaneGrimoireRecoveryBonus}from'../../src/data/lib/arcane-grimoire-recovery-source.js';import fs from'node:fs';import vm from'node:vm';import{createTceSpellBonusEngine}from'./tce-spell-bonus-native.mjs';
const read=p=>fs.readFileSync(new URL('../../src/'+p,import.meta.url),'utf8'),line=(s,n)=>{const x=s.split('\n').find(x=>new RegExp('^(?:export )?function '+n+'\\(').test(x));if(!x)throw Error('Actual native helper missing '+n);return x.replace(/^export /,'')};
export function createArcaneGrimoireEngine(options={}){
 const e=createTceSpellBonusEngine({item:'+1 Arcane Grimoire',main:'Wizard',secondary:'Warlock',spells:['Burning Hands','Fire Bolt'],secondarySpells:['Hold Person','Eldritch Blast'],...options}),c=e.c;
 const derivation=read('builder/11-logic-derivation.js'),multi=read('builder/14-logic-multiclass-hp-shop.js'),resource=read('builder/12i-logic-sheet-handlers-gear-resources.js');
 c.slotRecoveryAuthorityProblems=slotRecoveryAuthorityProblems;vm.runInContext(line(read('builder/03-logic-magic-item-effects.js'),'slotRecoveryAllocatedKeys'),c);
 for(const n of ['slugK','resKey'])vm.runInContext(line(derivation,n),c);
 vm.runInContext(derivation.slice(derivation.indexOf('export function resMax('),derivation.indexOf('/* M10:')).replace(/export /g,''),c);vm.runInContext(line(multi,'mcResMax'),c);
 const groups=[];c.registerSheetGroup=g=>groups.push(g);for(const id of ['res-init','res-class','res-hit-dice','res-multiclass','res-spell-slots']){const a=resource.indexOf('registerSheetGroup({id:"'+id+'"'),b=resource.indexOf('\nregisterSheet',a+1);if(a<0)throw Error('Missing native resource group '+id);let text=resource.slice(a,b<0?undefined:b);if(id==='res-class')text=text.slice(0,text.indexOf('/* M17:'));if(id==='res-hit-dice')text=text.slice(0,text.indexOf('registerSheetGroup({id:"res-multiclass"'));vm.runInContext(text,c)}
 const feature=read('builder/12j-logic-sheet-handlers-features.js');let classLabel;c.registerSheetGroup=g=>classLabel=g;const ca=feature.indexOf('registerSheetGroup({id:"class-label"'),cb=feature.indexOf('/* 2014 rules:',ca);vm.runInContext(feature.slice(ca,cb),c);
 loadArcaneGrimoireNative(c);const grimoireGroups=[];c.registerSheetGroup=g=>grimoireGroups.push(g);c.defineLocals=()=>{};vm.runInContext(read('builder/12zg-logic-arcane-grimoire-recovery.js').replace(/^import [^\n]*\n/gm,'').replace(/export /g,''),c);
 const baseProject=e.project,project=()=>{const out=baseProject(),parts=c.clsParts(),ctx={C:out,i:{B:c.B,c:c.classDef(c.B.cls),L:c.B.level,a:c.abilScores(),mcl:c.B.mc,parts},q:{resMax:c.resMax,mcResMax:c.mcResMax,resKey:c.resKey,slugK:c.slugK,slotsAll:c.slotsAll},patch:()=>({})};for(const id of ['res-init','res-class','res-hit-dice','res-multiclass','res-spell-slots'])groups.find(g=>g.id===id).run(ctx);classLabel.run(ctx);ctx.l={};ctx.i.ATT=c.attunementState();grimoireGroups.find(g=>g.id==='arcane-grimoire-resource-binding').run(ctx);grimoireGroups.find(g=>g.id==='arcane-grimoire-recovery-source').run(ctx);return out};
 const setC=e.setC;e.project=project;c.borrowedProjection=project;e.setC=value=>{setC(value);c.C=value};e.setC(project());return e;
}

export function nativeArcaneRecoveryRows(engine){const c=engine.c,helpers=read('app/05-logic-helpers.js'),casting=read('app/32b-logic-play-concentration-casting.js');for(const n of ['num','clamp'])vm.runInContext(line(helpers,n),c);c.C=engine.C;c.D={res:engine.C.res,level:c.TL()};c.sourceBonus=arcaneGrimoireRecoveryBonus;vm.runInContext(line(read('app/32aa-logic-arcane-grimoire-recovery.js'),'arcaneGrimoireRecoveryBonus'),c);for(const n of ['clsLvls','lvOf'])vm.runInContext(line(casting,n),c);vm.runInContext(line(read('app/08-ui-render-sheet-and-actions.js'),'used'),c);vm.runInContext(line(read('app/32d-logic-play-hp-rest-recovery.js'),'recList'),c);return c.recList();}
